package dev.alien.client.studio;
import dev.alien.client.config.*;import dev.alien.client.module.*;import dev.alien.client.scene.SceneConfig;import com.google.gson.Gson;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class StudioIntegrationTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void legacyProfilesRetainWidgetsCosmeticsAndOptionalFxOff(){ClientConfig c=new Gson().fromJson("{\"menuLayout\":\"Panels\",\"cosmetics\":{\"self\":{\"hat\":\"SAMURAI\"}}}",ClientConfig.class);c.normalize();assertEquals("Panels",c.menuLayout);assertEquals("SAMURAI",c.cosmetics.self.hat);assertEquals(15,c.hud.widgets.size());assertFalse(c.scenes.mist||c.scenes.afterglow||c.scenes.radiance||c.scenes.targetEsp||c.scenes.bokeh);assertFalse(c.studio.zoom||c.studio.nameTags||c.studio.handMovement);}
 @Test public void nonfiniteUniformsAndCameraInputsAreNormalized(){ClientConfig c=new ClientConfig();c.studio.cameraYaw=Float.NaN;c.studio.cameraDistance=Float.POSITIVE_INFINITY;c.studio.zoomFactor=-9;c.scenes.skySpeed=Float.NaN;c.scenes.skyBreathing=99;c.scenes.bokehStrength=Float.NEGATIVE_INFINITY;c.scenes.palette="invalid";c.normalize();assertEquals(25,c.studio.cameraYaw,0);assertEquals(25,c.studio.cameraDistance,0);assertEquals(1.5,c.studio.zoomFactor,0);assertEquals(1,c.scenes.skySpeed,0);assertEquals(3,c.scenes.skyBreathing,0);assertEquals(.6f,c.scenes.bokehStrength,0);assertEquals("Alien",c.scenes.palette);}
 @Test public void videoAndPreviousSkiesRemainSelectable(){Set<String> skies=new HashSet<>(Arrays.asList(SceneConfig.SKIES));for(String s:new String[]{"Galaxy","Aether","Nocturne","Amethyst","Opaline","Rain","Snow","Fire","Cosmic","BlackHole","Aurora","SnowClouds","Sunset","Ocean","Storm"}){assertTrue(skies.contains(s));SceneConfig c=new SceneConfig();c.sky=s;c.normalize();assertEquals(s,c.sky);}assertEquals(16,skies.size());}
 @Test public void galleryOnlyEditsActualPreferencesAndPreservesIndependentMasters(){ClientConfig c=new ClientConfig();List<StudioModules.Entry> entries=StudioModules.entries(c,ModuleManager.visuals(()->c,false));Set<String> ids=new HashSet<>();for(StudioModules.Entry e:entries)assertTrue(ids.add(e.id));StudioModules.Entry mist=entry(entries,"mist");mist.toggle();assertTrue(c.scenes.mist&&c.scenes.enabled);mist.toggle();assertFalse(c.scenes.mist);assertTrue(c.scenes.enabled);entry(entries,"hud_target").toggle();assertTrue(c.hud.widgets.get("target").enabled);entry(entries,"zoom").toggle();assertTrue(c.studio.zoom);assertFalse(c.combat.enabled);}
 @Test public void galleryMaterialSelectorsRestoreNaturalOnOff(){ClientConfig c=new ClientConfig();List<StudioModules.Entry> entries=StudioModules.entries(c,null);entry(entries,"scene_glass").toggle();assertEquals("Glass",c.scenes.mode);entry(entries,"scene_skeleton").toggle();assertEquals("Skeleton",c.scenes.mode);entry(entries,"scene_skeleton").toggle();assertEquals("Natural",c.scenes.mode);}
 @Test public void profilePreviewDoesNotReplaceLiveState()throws Exception{ConfigStore s=store();s.config().scenes.mist=true;s.saveProfile("one");s.config().scenes.mist=false;ClientConfig preview=s.previewProfile("one");assertTrue(preview.scenes.mist);assertFalse(s.config().scenes.mist);preview.scenes.mist=false;assertTrue(s.previewProfile("one").scenes.mist);}
 @Test public void duplicateRenameAndClipboardJsonRoundTripAllStudios()throws Exception{ConfigStore s=store();s.config().studio.scene="Sakura";s.config().studio.zoom=true;s.config().scenes.sky="Aether";s.config().scenes.skySpeed=1.7f;s.config().cosmetics.self.trail=true;s.saveProfile("one");s.duplicateProfile("one","two");s.renameProfile("two","renamed");s.importProfileJson("clipboard",s.profileJson("renamed"));assertEquals(Arrays.asList("clipboard","one","renamed"),s.listProfiles());assertTrue(s.loadProfile("clipboard"));assertEquals("Sakura",s.config().studio.scene);assertEquals("Aether",s.config().scenes.sky);assertEquals(1.7f,s.config().scenes.skySpeed,0);assertTrue(s.config().cosmetics.self.trail&&s.config().studio.zoom);}
 @Test public void renamePreservesServerAssociationAndActiveSaving()throws Exception{ConfigStore s=store();s.saveProfile("one");s.bindServer("server","one");assertTrue(s.loadServerProfile("server"));s.renameProfile("one","two");assertEquals("two",s.serverProfile("server"));s.config().studio.zoom=true;s.save();assertTrue(s.previewProfile("two").studio.zoom);assertFalse(s.listProfiles().contains("one"));}
 @Test public void importsRejectOverwriteTraversalDeepJsonAndUnsupportedVersion()throws Exception{ConfigStore s=store();s.saveProfile("one");for(String name:new String[]{"one","../escape"}){try{s.importProfileJson(name,"{}");fail();}catch(IOException expected){}}StringBuilder deep=new StringBuilder();for(int i=0;i<34;i++)deep.append("[");for(int i=0;i<34;i++)deep.append("]");for(String json:new String[]{deep.toString(),"{\"version\":99}","broken"}){try{s.importProfileJson("bad",json);fail();}catch(IOException expected){}}assertEquals(Collections.singletonList("one"),s.listProfiles());}
 @Test public void profileDiffReflectsActualSwitches(){ClientConfig a=new ClientConfig(),b=new ClientConfig();b.studio.zoom=true;b.studio.handMovement=true;int[] diff=ProfileLibraryScreen.changes(a,b);assertEquals(2,diff[0]);assertEquals(0,diff[1]);}
 private ConfigStore store()throws Exception{ConfigStore s=new ConfigStore(temp.newFolder());s.load();return s;}
 private StudioModules.Entry entry(List<StudioModules.Entry> entries,String id){for(StudioModules.Entry e:entries)if(e.id.equals(id))return e;throw new AssertionError(id);}
}
